import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Navbar from "./components/Navbar";
import Dashboard from "./components/Dashboard";
import Login from "./components/Login";
import Signup from "./components/Signup";
import Team from "./components/Team";
import LaptopsForm from "./components/LaptopsForm";
import LaptopsList from "./components/LaptopsList";

function App() {
  return (
    <Router>
      <Navbar /> {/* Ensure the Navbar is present on all pages */}
      <div className="container mx-auto mt-8 px-4">
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/login" element={<Login />} />
          <Route path="/signup" element={<Signup />} />
          <Route path="/team" element={<Team />} />
          <Route path="/laptops" element={<LaptopsForm />} /> {/* New Route */}
          <Route path="/laptops-list" element={<LaptopsList />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
